+ pinmux = <PINMUX_GPIO117__FUNC_URXD2>;
+ input-enable;
+ bias-pull-up;
+ };
+ pins-tx {
+ pinmux = <PINMUX_GPIO121__FUNC_UTXD2>;
+ };
+ pins-rts {
+ pinmux = <PINMUX_GPIO162__FUNC_URTS2>;
